// This file is generated by AI.

// 配音设置读取的测试。
//
// 两个诉求必须同时成立:
// * 用户自己调过的推理参数**一直保持** —— 不能被"改默认值"这种动作重置;
// * 但代码里改过默认值时, 老用户存储里那份**旧默认值**要能一次性迁过来, 否则新默认值
//   只在"从没打开过配音"的人身上生效。

import { afterEach, describe, expect, it } from 'vitest';

import { loadVoiceSettings, saveVoiceSettings } from '../src/voice/settings';
import { DEFAULT_VOICE_DEFAULTS } from '../src/voice/types';

const STORAGE_KEY = 'webgal-ink.voice';

let stored: string | null = null;

/** 用一份固定内容替换 localStorage (测试环境没有它) */
function stubStorage(value: string | null): void {
  stored = value;
  (globalThis as unknown as { localStorage: unknown }).localStorage = {
    getItem: (key: string) => (key === STORAGE_KEY ? stored : null),
    setItem: (key: string, next: string) => {
      if (key === STORAGE_KEY) stored = next;
    },
    removeItem: () => {
      stored = null;
    },
    clear: () => {
      stored = null;
    },
    key: () => null,
    length: 1,
  };
}

afterEach(() => {
  delete (globalThis as unknown as { localStorage?: unknown }).localStorage;
});

describe('loadVoiceSettings', () => {
  it('没有存储时用代码里的默认值', () => {
    stubStorage(null);
    const settings = loadVoiceSettings();
    expect(settings.defaults).toEqual(DEFAULT_VOICE_DEFAULTS);
    expect(settings.defaults.topK).toBe(40);
    expect(settings.defaults.topP).toBe(0.9);
    expect(settings.defaults.repetitionPenalty).toBe(1.2);
  });

  it('用户自己调过的值一直保持 (不会被默认值改动重置)', () => {
    stubStorage(
      JSON.stringify({
        version: 2,
        defaults: { language: 'ja', topK: 15, topP: 0.7, repetitionPenalty: 1.5, temperature: 0.8 },
      })
    );
    const settings = loadVoiceSettings();
    expect(settings.defaults.topK).toBe(15);
    expect(settings.defaults.topP).toBe(0.7);
    expect(settings.defaults.repetitionPenalty).toBe(1.5);
    expect(settings.defaults.temperature).toBe(0.8);
    expect(settings.defaults.language).toBe('ja');
  });

  it('旧版本存储里仍是旧默认值的项, 一次性迁到新默认值', () => {
    // 老用户的存储: 三个值都还是旧默认 (topK 5 / topP 1 / 惩罚 1.35), 没动过
    stubStorage(
      JSON.stringify({ launch: null, defaults: { language: 'auto', topK: 5, topP: 1, repetitionPenalty: 1.35 } })
    );
    const settings = loadVoiceSettings();
    expect(settings.defaults.topK).toBe(40);
    expect(settings.defaults.topP).toBe(0.9);
    expect(settings.defaults.repetitionPenalty).toBe(1.2);
  });

  it('迁移只动"仍是旧默认值"的项, 调过的项保留', () => {
    stubStorage(JSON.stringify({ defaults: { topK: 5, topP: 0.75, repetitionPenalty: 1.35 } }));
    const settings = loadVoiceSettings();
    expect(settings.defaults.topK).toBe(40); // 没动过 -> 跟随新默认
    expect(settings.defaults.topP).toBe(0.75); // 动过 -> 保留
    expect(settings.defaults.repetitionPenalty).toBe(1.2);
  });

  it('写入后带上版本号, 再次读取不再迁移', () => {
    stubStorage(null);
    saveVoiceSettings({
      launch: null,
      defaults: { ...DEFAULT_VOICE_DEFAULTS, topK: 12 },
      testSampleSteps: 4,
    });
    expect(stored).toContain('"version":2');
    expect(loadVoiceSettings().defaults.topK).toBe(12);
  });

  it('启动配置与测试步数照旧从存储读取', () => {
    stubStorage(JSON.stringify({ launch: { root: 'C:\\gsov' }, testSampleSteps: 8 }));
    const settings = loadVoiceSettings();
    expect(settings.launch?.root).toBe('C:\\gsov');
    expect(settings.testSampleSteps).toBe(8);
  });

  it('存储内容损坏时回退到默认值', () => {
    stubStorage('{ 半截 JSON');
    expect(loadVoiceSettings().defaults).toEqual(DEFAULT_VOICE_DEFAULTS);
  });
});
